import React from "react";
import { Container, Row, Col } from "react-bootstrap";
import Particle from "../Particle";
import Techstack from "./Techstack";
import Aboutcard from "./AboutCard";
import laptopImg from "../../Assets/about.png";
import Toolstack from "./Toolstack";
import SoftSkills from "./SoftSkills";
import usePageTitle from "../../hooks/usePageTitle";

function About() {
  usePageTitle("À propos | Maxime CURTIL");

  return (
    <>
      {" "}
      <Particle />
      <Container fluid className="about-section">
        <Container>
          <Row style={{ justifyContent: "center", padding: "10px" }}>
            <Col
              md={7}
              style={{
                justifyContent: "center",
                paddingTop: "30px",
                paddingBottom: "50px",
              }}
            >
              <h1 style={{ fontSize: "2.1em", paddingBottom: "20px" }}>
                Qui <strong className="purple">suis-je</strong> ?
              </h1>
              <Aboutcard />
            </Col>
            <Col md={5} style={{ paddingTop: "120px", paddingBottom: "50px" }} className="about-img">
              <img src={laptopImg} alt="about" className="img-fluid" />
            </Col>
          </Row>
          <h1 className="project-heading">
            Hard <strong className="purple">Skills </strong>
          </h1>

          <Techstack />

          <h1 className="project-heading">
            Soft <strong className="purple">Skills </strong>
          </h1>

          <SoftSkills />

          <h1 className="project-heading">
            Les <strong className="purple">outils</strong> que j'utilise
          </h1>
          <Toolstack />
        </Container>
      </Container>
    </>
  );
}

export default About;
